import json
import os
from scipy.stats import spearmanr
from statsmodels.stats.multitest import multipletests

os.makedirs("artifacts", exist_ok=True)

pw_results = {
    "Mistral-7B": {
        "n": 600,
        "sc": {"acc": 39.33, "n_correct": 236},
        "w1": {"acc": 40.17, "n_correct": 241, "delta_pp": 0.83, "mcnemar_p": 0.359283447265625, "b": 12, "c": 7},
        "w3": {"acc": 46.00, "n_correct": 276, "delta_pp": 6.67, "mcnemar_p": 1.1296023055413025e-05, "b": 61, "c": 21},
        "w5": {"acc": 50.33, "n_correct": 302, "delta_pp": 11.00, "mcnemar_p": 6.178035816936483e-07, "b": 120, "c": 54},
    },
    "LLaMA-3.1-8B": {
        "n": 600,
        "sc": {"acc": 72.50, "n_correct": 435},
        "w1": {"acc": 73.33, "n_correct": 440, "delta_pp": 0.83, "mcnemar_p": 0.359283447265625, "b": 12, "c": 7},
        "w3": {"acc": 73.33, "n_correct": 440, "delta_pp": 0.83, "mcnemar_p": 0.6646454904132133, "b": 45, "c": 40},
        "w5": {"acc": 72.00, "n_correct": 432, "delta_pp": -0.50, "mcnemar_p": 0.8707787409560847, "b": 74, "c": 77},
    },
    "Qwen2.5-14B": {
        "n": 600,
        "sc": {"acc": 74.00, "n_correct": 444},
        "w1": {"acc": 74.17, "n_correct": 445, "delta_pp": 0.17, "mcnemar_p": 1.0, "b": 3, "c": 2},
        "w3": {"acc": 74.67, "n_correct": 448, "delta_pp": 0.67, "mcnemar_p": 0.5034446716308594, "b": 12, "c": 8},
        "w5": {"acc": 75.17, "n_correct": 451, "delta_pp": 1.17, "mcnemar_p": 0.3603776529357674, "b": 25, "c": 18},
    },
    "Qwen3-14B": {
        "n": 600,
        "sc": {"acc": 85.83, "n_correct": 515},
        "w1": {"acc": 86.00, "n_correct": 516, "delta_pp": 0.17, "mcnemar_p": 1.0, "b": 1, "c": 0},
        "w3": {"acc": 86.33, "n_correct": 518, "delta_pp": 0.50, "mcnemar_p": 0.453125, "b": 5, "c": 2},
        "w5": {"acc": 87.00, "n_correct": 522, "delta_pp": 1.17, "mcnemar_p": 0.21003961563110352, "b": 15, "c": 8},
    },
}

folio_results = {
    "Mistral-7B": {
        "n": 204,
        "sc": {"acc": 55.88, "n_correct": 114},
        "w1": {"acc": 56.37, "n_correct": 115, "delta_pp": 0.49, "mcnemar_p": 1.0, "b": 4, "c": 3},
        "w3": {"acc": 58.82, "n_correct": 120, "delta_pp": 2.94, "mcnemar_p": 0.210113525390625, "b": 11, "c": 5},
    },
}

# Spearman
deberta_standalone = 55.00
generators = ["Mistral-7B", "LLaMA-3.1-8B", "Qwen2.5-14B", "Qwen3-14B"]
gaps = [deberta_standalone - pw_results[g]["sc"]["acc"] for g in generators]
gains = [pw_results[g]["w3"]["delta_pp"] for g in generators]
rho, p_spearman = spearmanr(gaps, gains)
print(f"Spearman rho={rho:.4f}, p={p_spearman:.4f}")
print(f"  gaps:  {gaps}")
print(f"  gains: {gains}")

# BH correction
test_labels = []
raw_pvals = []
for g in generators:
    for w in [1, 3, 5]:
        test_labels.append(f"{g}_w{w}")
        raw_pvals.append(pw_results[g][f"w{w}"]["mcnemar_p"])

rejected, pvals_corrected, _, _ = multipletests(raw_pvals, alpha=0.05, method='fdr_bh')
n_sig = int(sum(rejected))
print(f"\nBH correction (m=12), significant: {n_sig}/12")
for label, raw_p, adj_p, sig in zip(test_labels, raw_pvals, pvals_corrected, rejected):
    marker = "*" if sig else " "
    print(f"  {marker} {label:25s} raw={raw_p:.2e}  adj={adj_p:.2e}")

# SC baseline shift
old_counter = {"Mistral-7B": 236, "LLaMA-3.1-8B": 420, "Qwen2.5-14B": 441, "Qwen3-14B": 510}
old_combo_w3 = {"Mistral-7B": 42.83, "LLaMA-3.1-8B": 74.17, "Qwen2.5-14B": 74.33, "Qwen3-14B": 86.00}
old_sc_pct = {"Mistral-7B": 39.33, "LLaMA-3.1-8B": 70.00, "Qwen2.5-14B": 73.50, "Qwen3-14B": 85.00}

print("\n=== SC baseline: counter → alpha ===")
for g in generators:
    d = pw_results[g]["sc"]["n_correct"] - old_counter[g]
    print(f"  {g}: {old_counter[g]} → {pw_results[g]['sc']['n_correct']} ({d:+d})")

print("\n=== Combo w3 delta: old → new ===")
for g in generators:
    old_d = old_combo_w3[g] - old_sc_pct[g]
    new_d = pw_results[g]["w3"]["delta_pp"]
    print(f"  {g}: {old_d:+.2f}pp → {new_d:+.2f}pp")

# Build output
output = {
    "proofwriter": pw_results,
    "folio": folio_results,
    "spearman": {
        "generators": generators,
        "deberta_standalone": deberta_standalone,
        "gaps": [round(g, 2) for g in gaps],
        "gains": [round(g, 2) for g in gains],
        "rho": round(float(rho), 4),
        "p": round(float(p_spearman), 4)
    },
    "bh_correction": {
        "m": 12,
        "test_labels": test_labels,
        "raw_pvals": [round(p, 10) for p in raw_pvals],
        "adjusted_pvals": [round(float(p), 10) for p in pvals_corrected],
        "significant_after_bh": [bool(r) for r in rejected],
        "n_significant": n_sig
    },
    "sc_baseline_shift": {
        "note": "Alphabetical tiebreaking (with invalid-answer filtering) changes SC baselines from combo traces",
        "changes": {g: {
            "counter_n": old_counter[g],
            "alpha_n": pw_results[g]["sc"]["n_correct"],
            "diff": pw_results[g]["sc"]["n_correct"] - old_counter[g]
        } for g in generators}
    },
    "paper_changes_needed": [
        {
            "section": "NLI Combo Table",
            "description": "SC baselines shift: LLaMA 420→435(+15), Qwen2.5 441→444(+3), Qwen3 510→515(+5), Mistral unchanged. Combo gains shrink. Only Mistral w3/w5 remain significant after BH.",
            "old_significant_count": 4,
            "new_significant_count": n_sig
        },
        {
            "section": "Spearman correlation (capability gap vs combo gain)",
            "description": f"rho={round(float(rho), 4)}, p={round(float(p_spearman), 4)}"
        },
        {
            "section": "FOLIO combo",
            "description": "Mistral FOLIO SC=55.88%(114/204), w1=56.37%(+0.49pp,p=1.0), w3=58.82%(+2.94pp,p=0.21)"
        }
    ]
}

out_path = "artifacts/nli_combo_recomputed.json"
with open(out_path, "w") as f:
    json.dump(output, f, indent=2)
print(f"\nSaved: {out_path}")
PYEOF
